student_name = #{studentName}, student_phone = #{studentPhone}, student_email = #{studentEmail}, student_address = #{studentAddress}, student_school = #{studentSchool}, student_grade = #{studentGrade}, student_gender = #{studentGender}, parent_name = #{parentName}, parent_phone = #{parentPhone}, parent_email = #{parentEmail}, customer_memo = #{customerMemo}, customer_utime = systimestamp
